<template>
  <main class="page-main"><div class="shell narrow-shell"><div class="page-title-row"><div><span class="eyebrow">Conta</span><h1>Perfil e preferências</h1><p>Dados demonstrativos do utilizador autenticado.</p></div></div><section class="profile-card"><div class="profile-hero"><span class="avatar xl">{{ initials }}</span><div><h2>{{ profileName }}</h2><p>{{ roleLabel }}</p></div></div><form @submit.prevent="save"><div class="form-grid two"><label>Nome completo<input v-model="name" /></label><label>Contacto<input v-model="phone" /></label></div><label>E-mail<input v-model="email" /></label><label v-if="store.role==='client'">Localização preferida<select><option>Maputo</option><option>Matola</option></select></label><div class="toggle-list"><label><span><strong>Notificações de marcação</strong><small>Confirmações e alterações</small></span><input type="checkbox" checked /></label><label><span><strong>Lembretes</strong><small>Aviso antes do atendimento</small></span><input type="checkbox" checked /></label><label><span><strong>Promoções</strong><small>Ofertas dos salões</small></span><input type="checkbox" /></label></div><button class="btn btn-primary">Guardar alterações</button></form></section><button class="btn btn-outline full role-action" @click="store.roleSwitcherOpen=true">Mudar perfil de demonstração</button></div></main>
</template>
<script>
import { appStore as store, showToast } from '../store'
export default { name:'ProfileView', data(){return{store,name:store.user.name,email:store.user.email,phone:store.user.phone}}, computed:{initials(){return this.name.split(' ').map(x=>x[0]).slice(0,2).join('')},profileName(){return store.role==='professional'?'Celso Mucavele':store.role==='salonAdmin'?'Administração · Beleza & Estilo':store.role==='platformAdmin'?'Administrador da Plataforma':this.name},roleLabel(){return({client:'Cliente',professional:'Profissional',salonAdmin:'Administrador do Salão',platformAdmin:'Administrador da Plataforma'})[store.role]}}, methods:{save(){store.user.name=this.name;store.user.email=this.email;store.user.phone=this.phone;showToast('Perfil actualizado no mockup.')}} }
</script>
